SELECT * FROM public.seed_starter_documents('[{"slug":"partner-operations-guide-ar","title":"دليل عمل الشريك","subtitle":"درب — دليل تشغيلي رسمي للشركاء","description":"دليل شامل للشركاء: الدور، الإحالة، العمولات، فترة التثبيت، والمدفوعات.","category":"partners","doc_kind":"guide","language":"ar","content":[{"id":"pg_ar_0","type":"cover","title":"دليل عمل الشريك","subtitle":"درب — دليل تشغيلي رسمي للشركاء","note":"الإصدار {{version}} · تاريخ السريان {{effective_date}}"},{"id":"pg_ar_1","type":"heading","level":1,"text":"عن درب"},{"id":"pg_ar_2","type":"paragraph","text":"درب وكالة متخصّصة بمرافقة الطلاب من مرحلة الاستفسار الأولي وحتى التسجيل والوصول إلى ألمانيا. تُدار كل حالة داخل منصّة درب، ويكون لكل شريك لوحة تحكّم خاصة به."},{"id":"pg_ar_3","type":"heading","level":1,"text":"من هو الشريك؟"},{"id":"pg_ar_4","type":"paragraph","text":"الشريك هو جهة تعاون تُحيل الطلاب إلى درب عبر رابطها الخاص. يحصل الشريك على عمولة ثابتة عن كل طالب يصل إلى مرحلة الدفع والتسجيل المؤكّد."},{"id":"pg_ar_5","type":"heading","level":1,"text":"مسؤوليات الشريك"},{"id":"pg_ar_6","type":"list","items":["عرض خدمات درب بدقّة وبالاعتماد على المعلومات الرسمية المنشورة في المنصّة.","توجيه الطالب إلى رابط التقديم الرسمي دون جمع مستندات أو مبالغ بشكل شخصي.","المحافظة على خصوصية بيانات الطلاب وعدم مشاركتها خارج المنصّة.","التواصل مع الإدارة عبر صندوق المحادثة داخل لوحة التحكّم."]},{"id":"pg_ar_7","type":"heading","level":1,"text":"الوضع القانوني للشريك"},{"id":"pg_ar_8","type":"paragraph","text":"الشريك مقدّم خدمة مستقلّ. لا تنشئ هذه العلاقة علاقة عمل أو استخدام أو شراكة قانونية مع درب."},{"id":"pg_ar_9","type":"callout","tone":"warning","text":"الشريك مسؤول بشكل كامل عن التزاماته الضريبية والقانونية الشخصية الناتجة عن العمولات التي يتقاضاها."},{"id":"pg_ar_a","type":"heading","level":1,"text":"مسارات العمل"},{"id":"pg_ar_b","type":"list","items":["مشاركة رابط التقديم الشخصي مع الطلاب المهتمّين.","متابعة الحالات المنسوبة عبر لوحة التحكّم.","تقديم معلومات دقيقة عن البرامج والأسعار المعتمدة."]},{"id":"pg_ar_c","type":"heading","level":2,"text":"ممنوع منعًا باتًا"},{"id":"pg_ar_d","type":"list","items":["تقديم وعود بقبول جامعي أو تأشيرة أو نتيجة مضمونة.","الإعلان عن أسعار أو خصومات غير معتمدة من الإدارة.","تحصيل أي مبلغ مالي من الطالب باسم درب.","التعريف عن النفس كموظّف لدى درب."]},{"id":"pg_ar_e","type":"pagebreak"},{"id":"pg_ar_f","type":"heading","level":1,"text":"مسار الإحالة"},{"id":"pg_ar_g","type":"paragraph","text":"عندما يقدّم الطالب طلبه عبر رابط الشريك، تُنسب الحالة إليه تلقائيًا. العمولة ثابتة وتُستحق عند وصول الحالة إلى مرحلة التسجيل المؤكّد، ثم تدخل فترة تثبيت مدّتها {{lock_days}} يومًا."},{"id":"pg_ar_h","type":"flow","title":"مسار الإحالة","steps":["الشريك","رابط التقديم","الطالب","درب"]},{"id":"pg_ar_i","type":"heading","level":1,"text":"العمولات"},{"id":"pg_ar_j","type":"paragraph","text":"العمولات مبالغ ثابتة بالشيكل الجديد كما هي معرّفة في مركز العمولات. القيم أدناه وفق الإعدادات الفعليّة:"},{"id":"pg_ar_k","type":"table","headers":["نوع الإحالة","مستحقّ العمولة","المبلغ"],"rows":[["طالب أحاله الشريك مباشرة","الشريك","{{partner_amount}}"],["طالب أحاله سفير","السفير","{{ambassador_amount}}"]]},{"id":"pg_ar_l","type":"heading","level":1,"text":"الإلغاء والاسترداد"},{"id":"pg_ar_m","type":"paragraph","text":"المبدأ التشغيلي: العمولة مرتبطة بحالة مدفوعة ومؤكّدة، وأي إلغاء أو استرداد لاحق ينعكس على العمولة المرتبطة بها."},{"id":"pg_ar_n","type":"callout","tone":"legal","title":"يتطلّب مراجعة قانونية","text":"الصياغة التفصيلية لحالات الإلغاء والاسترداد وآثارها على العمولات تحتاج إلى مراجعة قانونية قبل الاعتماد النهائي."},{"id":"pg_ar_o","type":"heading","level":1,"text":"المدفوعات"},{"id":"pg_ar_p","type":"paragraph","text":"تُصرف العمولات المتاحة عبر تحويل بنكي بعد تقديم طلب سحب من لوحة التحكّم، وتراجع الإدارة كل طلب قبل التنفيذ."},{"id":"pg_ar_q","type":"heading","level":1,"text":"الإشعارات"},{"id":"pg_ar_r","type":"list","items":["إشعار عند تسجيل عمولة جديدة.","إشعار عند تغيّر حالة طلب السحب.","رسائل الإدارة عبر صندوق المحادثة."]},{"id":"pg_ar_s","type":"heading","level":1,"text":"إنهاء التعاون والمسؤولية والاختصاص القضائي"},{"id":"pg_ar_t","type":"callout","tone":"legal","title":"يتطلّب مراجعة قانونية","text":"بنود إنهاء التعاون وحدود المسؤولية والاختصاص القضائي لم تُصَغ في هذا الإصدار، وتحتاج إلى مراجعة قانونية قبل نشر أي نسخة مُلزِمة."},{"id":"pg_ar_u","type":"heading","level":1,"text":"إقرار"},{"id":"pg_ar_v","type":"paragraph","text":"بتوقيعه أدناه يقرّ الشريك بأنّه اطّلع على هذا الدليل التشغيلي وفهم مضمونه. هذا الدليل وثيقة تشغيلية توضيحية وليس عقدًا مُلزِمًا."},{"id":"pg_ar_w","type":"signature","parties":["عن درب","الشريك: {{partner_name}}"]},{"id":"pg_ar_x","type":"disclaimer","text":"وثيقة داخلية صادرة عن درب. القيم المالية الواردة فيها تعكس إعدادات النظام بتاريخ {{date}} وقد تتغيّر بقرار من الإدارة."}],"status":"draft","current_version":"1.0","change_note":"Initial version"},{"slug":"ambassador-guide-ar","title":"دليل السفير","subtitle":"درب — دليل تشغيلي رسمي للسفراء","description":"دليل شامل للسفراء: الدور، الإحالة، العمولات، فترة التثبيت، والمدفوعات.","category":"ambassadors","doc_kind":"guide","language":"ar","content":[{"id":"am_ar_0","type":"cover","title":"دليل السفير","subtitle":"درب — دليل تشغيلي رسمي للسفراء","note":"الإصدار {{version}} · تاريخ السريان {{effective_date}}"},{"id":"am_ar_1","type":"heading","level":1,"text":"عن درب"},{"id":"am_ar_2","type":"paragraph","text":"درب وكالة متخصّصة بمرافقة الطلاب حتى التسجيل والوصول إلى ألمانيا. لكل سفير لوحة تحكّم خاصة به لمتابعة إحالاته وأرباحه."},{"id":"am_ar_3","type":"heading","level":1,"text":"من هو السفير؟"},{"id":"am_ar_4","type":"paragraph","text":"السفير شريك إعلامي يُحيل الطلاب إلى درب عبر رابطه الخاص، ويحصل على عمولة ثابتة عن كل طالب يصل إلى مرحلة التسجيل المؤكّد."},{"id":"am_ar_5","type":"heading","level":1,"text":"مسؤوليات السفير"},{"id":"am_ar_6","type":"list","items":["عرض خدمات درب بدقّة عبر منصّاته الإعلامية.","توجيه الطالب إلى رابط التقديم الرسمي.","المحافظة على خصوصية بيانات الطلاب.","التواصل مع الإدارة عبر صندوق المحادثة."